    Gson customGson = new GsonBuilder().registerTypeAdapter(ZoneId.class, zoneIdAdapter).create();
    ZoneId zoneId = ZoneId.of("UTC+01:00");
    int totalSeconds = ((ZoneOffset) zoneId.normalized()).getTotalSeconds();
