package com.google.gson.internal;

import static com.google.common.truth.Truth.assertThat;

import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.ObjectInputStream;
import java.io.ObjectOutputStream;
import java.math.BigDecimal;
import org.junit.Test;

public class LazilyParsedNumberTest {
  @Test
  public void testHashCode() {
    LazilyParsedNumber n1 = new LazilyParsedNumber("1");
    LazilyParsedNumber n1Another = new LazilyParsedNumber("1");
    assertThat(n1Another.hashCode()).isEqualTo(n1.hashCode());
  }

  @Test
  public void testEquals() {
    LazilyParsedNumber n1 = new LazilyParsedNumber("1");
    LazilyParsedNumber n1Another = new LazilyParsedNumber("1");
    assertThat(n1.equals(n1Another)).isTrue();
  }

  @Test
  public void testEqualsOtherNumberTypes() {
    LazilyParsedNumber n = new LazilyParsedNumber("1");
    // LazilyParsedNumber should be equal to other Number types with the same value
    assertThat(n.equals(Integer.valueOf(1))).isTrue();
    assertThat(n.equals(Long.valueOf(1L))).isTrue();
    assertThat(n.equals(new BigDecimal("1"))).isTrue();
  }

  @Test
  public void testJavaSerialization() throws IOException, ClassNotFoundException {
    ByteArrayOutputStream out = new ByteArrayOutputStream();
    ObjectOutputStream objOut = new ObjectOutputStream(out);
    objOut.writeObject(new LazilyParsedNumber("123"));
    objOut.close();

    ObjectInputStream objIn = new ObjectInputStream(new ByteArrayInputStream(out.toByteArray()));
    Number deserialized = (Number) objIn.readObject();
    assertThat(deserialized).isEqualTo(new BigDecimal("123"));
  }
}

